/**
 * Browser-only login, used for the static GitHub Pages build (no server available).
 *
 * Passwords are checked against PBKDF2-SHA256 hashes (600k iterations) in static-users.json,
 * generated by `npm run user:password`. The passwords themselves are long random strings and
 * never stored in plain text, so the published hashes don't reveal them.
 *
 * Limitation: in a static site the gate runs in the visitor's browser, so a technical person can
 * bypass it. It keeps casual visitors out; it is not access control for sensitive data.
 */
import data from './static-users.json';
import type { LoginResult, User } from './api';

interface StaticUser extends User {
  salt: string;
  hash: string;
}

interface Session {
  u: string;
  v: string; // hash fingerprint: a password change ends old sessions
  exp: number;
}

const USERS = data.users as StaticUser[];
const ITERATIONS = data.iterations;
const SESSION_KEY = 'roboyell-kanban:session';
const LOCK_KEY = 'roboyell-kanban:login-lock';
const SESSION_TTL_MS = 12 * 60 * 60 * 1000;
const REMEMBER_TTL_MS = 30 * 24 * 60 * 60 * 1000;
const MAX_FAILURES = 5;
const LOCK_MS = 5 * 60 * 1000;

const hexToBytes = (hex: string) => new Uint8Array(hex.match(/../g)!.map((b) => parseInt(b, 16)));
const bytesToHex = (bytes: Uint8Array) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
const fingerprint = (u: StaticUser) => u.hash.slice(0, 16);
const publicUser = (u: StaticUser): User => ({ username: u.username, name: u.name });

function normalizeLogin(value: string): string {
  return value.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

async function pbkdf2(password: string, saltHex: string): Promise<string> {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', hash: 'SHA-256', salt: hexToBytes(saltHex), iterations: ITERATIONS },
    key,
    256,
  );
  return bytesToHex(new Uint8Array(bits));
}

function safeGet(storage: Storage, key: string): string | null {
  try {
    return storage.getItem(key);
  } catch {
    return null;
  }
}

function readSession(): Session | null {
  const raw = safeGet(sessionStorage, SESSION_KEY) ?? safeGet(localStorage, SESSION_KEY);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as Session;
  } catch {
    return null;
  }
}

function clearSession() {
  try {
    sessionStorage.removeItem(SESSION_KEY);
    localStorage.removeItem(SESSION_KEY);
  } catch {
    /* ignore */
  }
}

type LockState = Record<string, { count: number; until: number }>;

function readLocks(): LockState {
  try {
    return JSON.parse(localStorage.getItem(LOCK_KEY) ?? '{}') as LockState;
  } catch {
    return {};
  }
}

function writeLocks(state: LockState) {
  try {
    localStorage.setItem(LOCK_KEY, JSON.stringify(state));
  } catch {
    /* ignore */
  }
}

export async function staticCurrentUser(): Promise<User | null> {
  const session = readSession();
  if (!session || session.exp < Date.now()) return null;
  const user = USERS.find((u) => u.username === session.u);
  return user && fingerprint(user) === session.v ? publicUser(user) : null;
}

export async function staticLogin(login: string, password: string, remember: boolean): Promise<LoginResult> {
  const key = normalizeLogin(login);
  if (!key || !password) return { ok: false, error: 'Informe usuário e senha.' };

  const locks = readLocks();
  const lock = locks[key];
  if (lock && lock.until > Date.now()) {
    return { ok: false, error: `Muitas tentativas. Tente novamente em ${Math.ceil((lock.until - Date.now()) / 60_000)} min.` };
  }

  const user = USERS.find((u) => u.username === key || normalizeLogin(u.name) === key);
  // Always run the hash so timing doesn't reveal which usernames exist.
  const hash = await pbkdf2(password, user?.salt ?? '00'.repeat(16));
  if (!user || hash !== user.hash) {
    const count = (lock?.count ?? 0) + 1;
    if (count >= MAX_FAILURES) {
      locks[key] = { count: 0, until: Date.now() + LOCK_MS };
      writeLocks(locks);
      return { ok: false, error: `Muitas tentativas. Tente novamente em ${LOCK_MS / 60_000} min.` };
    }
    locks[key] = { count, until: 0 };
    writeLocks(locks);
    const left = MAX_FAILURES - count;
    return { ok: false, error: left <= 2 ? `Usuário ou senha inválidos. ${left} tentativa(s) restante(s).` : 'Usuário ou senha inválidos.' };
  }

  delete locks[key];
  writeLocks(locks);
  clearSession();
  const session: Session = { u: user.username, v: fingerprint(user), exp: Date.now() + (remember ? REMEMBER_TTL_MS : SESSION_TTL_MS) };
  try {
    (remember ? localStorage : sessionStorage).setItem(SESSION_KEY, JSON.stringify(session));
  } catch {
    /* storage blocked: session lasts only for this page view */
  }
  return { ok: true, user: publicUser(user) };
}

export async function staticLogout(): Promise<void> {
  clearSession();
}
